/**
 * 统计接口 mock：实现页 5 个统计接口按设计稿数值返回（{code:200,msg:'success',data:…}）。
 * 仅注册在本页（openMine）内，基准页 file:// 不受影响；不改 .env.test 与生产逻辑。
 * 关键数据导航卡标签不在 API_STAT_LABELS（纯静态），getKeyData 返回空对象即可。
 */
async function mockStatApis(page: Page) {
  const ok = (data: unknown) => ({
    status: 200,
    contentType: 'application/json',
    body: JSON.stringify({ code: 200, msg: 'success', data }),
  })
  await page.route('**/v2.0/property/portal/getKeyData*', (r) => r.fulfill(ok({})))
  await page.route('**/v2.0/benefit/portal/getBenefitData*', (r) =>
    r.fulfill(ok({ monthOrgNum: 6, monthAccountNum: 5, monthAgreementNum: 4, fundAmount: 1286.44 })),
  )
  await page.route('**/v2.0/property/portal/getRepairData*', (r) =>
    r.fulfill(
      ok({
        monthAddNum: 14860,
        monthCompletedNum: 14145,
        monthUncompletedNum: 715,
        satisfactionRate: '97.2%',
      }),
    ),
  )
  await page.route('**/v2.0/msg/publicNotice/statistics/overview*', (r) =>
    r.fulfill(ok({ propertyServiceCount: 5390, publicBenefitCount: 2187, maintenanceFundCount: 1076 })),
  )
  await page.route('**/v2.0/system/region/list*', (r) =>
    r.fulfill(
      ok(
        ['张家港市', '常熟市', '太仓市', '昆山市', '吴江区'].map((regionName) => ({ regionName })),
      ),
    ),
  )
}

